68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
75	     * owner's id, customer code, registration date and membership level, so the create side-effect
76	     * can be audited independently of the application log.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    /**
89	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
90	     * and a domain containing at least one dot, with no whitespace in any segment.
91	     */
92	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
93	
94	    /**
95	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
96	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
97	     */
98	    private static final int MAX_OWNERS_PER_CITY = 50;
99	
100	    /**
101	     * Maximum number of owners that may be registered on a single day (by registration date). A create
102	     * attempted once this many owners already carry today's registration date is rejected with a
103	     * 429 Too Many Requests.
104	     */
105	    private static final int MAX_OWNERS_PER_DAY = 100;
106	
107	    /**
108	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
109	     * owners already carry the new owner's registration date, the created owner is flagged
110	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
111	     */
112	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
113	
114	    /**
115	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
116	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
117	     */
118	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
119	        "ST", "STREET",
120	        "RD", "ROAD",
121	        "AVE", "AVENUE");
