133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
161	        validateRequiredFields(ownerFieldsDto);
162	        HttpHeaders headers = new HttpHeaders();
163	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
164	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
165	        owner.setRegistrationDate(registrationDate);
166	        requireDailyCapacity(registrationDate);
167	        requireCityHasCapacity(owner.getCity());
168	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
169	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
170	            joinHousehold(owner);
171	        } else {
172	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
173	        }
174	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
175	        requireUniqueTelephone(telephone);
176	        owner.setTelephone(telephone);
177	        String email = normalizeEmail(ownerFieldsDto.getEmail());
178	        requireUniqueEmail(email);
179	        owner.setEmail(email);
180	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
181	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
182	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
183	        this.clinicService.saveOwner(owner);
184	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
185	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        headers.setLocation(UriComponentsBuilder.newInstance()
188	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
189	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    /**
193	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
194	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
195	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
196	     * existed prior to this create.
197	     *
198	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
199	     *     a business day
200	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
201	     *     registered on that business day
202	     */
203	    private void requireDailyCapacity(LocalDate registrationDate) {
204	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
205	            throw new DailyOwnerLimitException(registrationDate);
206	        }
207	    }
208	
209	    /**
210	     * Counts the existing owners whose registration date equals the given business-day date. This is
211	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
212	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
213	     * the bulk-signup warning.
214	     *
215	     * @param registrationDate the effective business-day registration date to count against
216	     * @return the number of pre-existing owners registered on that date
217	     */
218	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
219	        return this.clinicService.findAllOwners().stream()
220	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
221	            .count();
222	    }
223	
224	    /**
225	     * Rejects an owner whose city already contains the maximum allowed number of owners
226	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
227	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
228	     * create.
229	     *
230	     * @param city the city of the owner being created
231	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
232	     */
233	    private void requireCityHasCapacity(String city) {
234	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
236	            .count();
237	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
238	            throw new CityOwnerLimitException(city);
239	        }
240	    }
241	
242	    /**
243	     * Generates the customer code for a newly created owner, formatted
244	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
245	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
246	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
247	     * that city (e.g. {@code 'LON-SMI-0007'}).
248	     *
249	     * @param city the owner's city
250	     * @param lastName the owner's last name
251	     * @return the generated customer code
252	     */
253	    private String generateCustomerCode(String city, String lastName) {
254	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
255	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
256	        int sequence = (int) this.clinicService.findAllOwners().stream()
257	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
258	            .count() + 1;
259	        return String.format("%s-%s-%04d", city3, last3, sequence);
260	    }
261	
262	    /**
263	     * Counts the existing owners that already share the given first name and last name, compared
264	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
265	     * owners that existed prior to this create.
266	     *
267	     * @param firstName the first name of the owner being created
268	     * @param lastName the last name of the owner being created
269	     * @return the number of pre-existing namesakes
270	     */
271	    private int countNamesakes(String firstName, String lastName) {
272	        return (int) this.clinicService.findAllOwners().stream()
273	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
274	                && equalsIgnoreCase(existing.getLastName(), lastName))
275	            .count();
276	    }
277	
278	    /**
279	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
280	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
281	     *
282	     * @param a the first value, possibly {@code null}
283	     * @param b the second value, possibly {@code null}
284	     * @return whether the values are equal ignoring case
285	     */
286	    private boolean equalsIgnoreCase(String a, String b) {
287	        return a == null ? b == null : a.equalsIgnoreCase(b);
288	    }
289	
290	    /**
291	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
292	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
293	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
294	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
295	     *
296	     * @param ownerFieldsDto the submitted owner fields
297	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
298	     */
299	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
300	        List<String> invalidFields = new ArrayList<>();
301	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
302	            invalidFields.add("firstName");
303	        }
304	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
305	            invalidFields.add("lastName");
306	        }
307	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
308	            invalidFields.add("address");
309	        }
310	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
311	            invalidFields.add("city");
312	        }
313	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
314	            invalidFields.add("telephone");
315	        }
316	        if (!invalidFields.isEmpty()) {
317	            throw new InvalidOwnerFieldsException(invalidFields);
318	        }
319	    }
320	
321	    /**
322	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
323	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
324	     * what gets stored and returned.
325	     *
326	     * @param telephone the raw telephone value from the request
327	     * @return the normalized E.164 telephone number
328	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
329	     */
330	    private String normalizeTelephone(String telephone) {
331	        String e164 = toE164(telephone);
332	        if (e164 == null) {
333	            throw new InvalidOwnerFieldsException(List.of("telephone"));
334	        }
335	        return e164;
336	    }
337	
338	    /**
339	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
340	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
341	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
342	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
343	     * it contains 8 to 15 digits after the {@code '+'}.
344	     *
345	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
346	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
347	     *
348	     * @param telephone the raw telephone value, possibly {@code null}
349	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
350	     */
351	    private String toE164(String telephone) {
352	        if (telephone == null) {
353	            return null;
354	        }
355	        String cleaned = telephone.replaceAll("[ \\-()]", "");
356	        String digits;
357	        if (cleaned.startsWith("+")) {
358	            digits = cleaned.substring(1);
359	        } else {
360	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
361	            digits = "61" + national;
362	        }
363	        if (!digits.matches("[0-9]{8,15}")) {
364	            return null;
365	        }
366	        return "+" + digits;
367	    }
368	
369	    /**
370	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
371	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
372	     * and returned lower-cased.
373	     *
374	     * @param email the raw email value from the request, possibly {@code null}
375	     * @return the lower-cased email, or {@code null} when none was supplied
376	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
377	     */
378	    private String normalizeEmail(String email) {
379	        if (!StringUtils.hasText(email)) {
380	            return null;
381	        }
382	        String trimmed = email.trim();
383	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
384	            throw new InvalidOwnerFieldsException(List.of("email"));
385	        }
386	        return trimmed.toLowerCase(Locale.ROOT);
387	    }
388	
389	    /**
390	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
391	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
392	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
393	     *
394	     * @param telephone the normalized (E.164) telephone of the owner being created
395	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
396	     */
397	    private void requireUniqueTelephone(String telephone) {
398	        boolean inUse = this.clinicService.findAllOwners().stream()
399	            .map(Owner::getTelephone)
400	            .filter(existing -> existing != null)
401	            .map(existing -> {
402	                String e164 = toE164(existing);
403	                return e164 != null ? e164 : existing;
404	            })
405	            .anyMatch(telephone::equals);
406	        if (inUse) {
407	            throw new DuplicateTelephoneException(telephone);
408	        }
409	    }
410	
411	    /**
412	     * Rejects an owner whose email, compared by its lower-cased form, is already used by an existing
413	     * owner. This enforces that no two owners share the same email case-insensitively. An absent
414	     * ({@code null}) email is always allowed, since no email is being claimed. Existing values are
415	     * compared by their lower-cased form, so a stored value in any casing is matched.
416	     *
417	     * @param email the normalized (lower-cased) email of the owner being created, or {@code null}
418	     * @throws DuplicateEmailException if another owner already has this email (compared lower-cased)
419	     */
420	    private void requireUniqueEmail(String email) {
421	        if (email == null) {
422	            return;
423	        }
424	        boolean inUse = this.clinicService.findAllOwners().stream()
425	            .map(Owner::getEmail)
426	            .filter(existing -> existing != null)
427	            .anyMatch(existing -> existing.toLowerCase(Locale.ROOT).equals(email));
428	        if (inUse) {
429	            throw new DuplicateEmailException(email);
430	        }
431	    }
432	
433	    /**
434	     * Rejects an owner whose last name and address match those of an existing owner, where both are
435	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
436	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
437	     *
438	     * @param lastName the last name of the owner being created
439	     * @param address the address of the owner being created
440	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
441	     */
442	    private void requireUniqueHousehold(String lastName, String address) {
443	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
444	            throw new DuplicateHouseholdException(lastName, address);
445	        }
446	    }
447	
448	    /**
449	     * Returns the existing owners that belong to the same household as the given last name and
450	     * address, i.e. those whose last name and address match case-insensitively and with runs of
451	     * whitespace collapsed to a single space.
452	     *
453	     * @param lastName the last name to match
454	     * @param address the address to match
455	     * @return the matching owners (possibly empty, never {@code null})
456	     */
457	    private List<Owner> findHouseholdMembers(String lastName, String address) {
458	        String normalizedLastName = normalizeForHousehold(lastName);
459	        String normalizedAddress = normalizeAddress(address);
460	        return this.clinicService.findAllOwners().stream()
461	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
462	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
463	            .toList();
464	    }
465	
466	    /**
467	     * Joins the owner being created to the shared household of any existing owner(s) that have the
468	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
469	     * member of the household - the existing owners and the new one - is assigned the same stable
470	     * {@code householdId}, so the shared identifier can be read back from any of them.
471	     *
472	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
473	     * the owner is left without a {@code householdId}.
474	     *
475	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
476	     * the household's member count after this create ({@code householdSize}), so the shared size can
477	     * be read back from any of them.
478	     *
479	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
480	     */
481	    private void joinHousehold(Owner owner) {
482	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
483	        if (members.isEmpty()) {
484	            return;
485	        }
486	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
487	        int householdSize = members.size() + 1;
488	        owner.setHouseholdId(householdId);
489	        owner.setHouseholdSize(householdSize);
490	        for (Owner member : members) {
491	            member.setHouseholdId(householdId);
492	            member.setHouseholdSize(householdSize);
493	            this.clinicService.saveOwner(member);
494	        }
495	    }
496	
497	    /**
498	     * Computes the stable, shared household identifier for a last name and address. The value is
499	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
500	     * name and address, so every owner in the same household computes the same identifier.
501	     *
502	     * @param lastName the last name of the household
503	     * @param address the address of the household
504	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
505	     */
506	    private String computeHouseholdId(String lastName, String address) {
507	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
508	        try {
509	            byte[] digest = MessageDigest.getInstance("SHA-256")
510	                .digest(key.getBytes(StandardCharsets.UTF_8));
511	            StringBuilder hex = new StringBuilder();
512	            for (int i = 0; i < 6; i++) {
513	                hex.append(String.format("%02X", digest[i]));
514	            }
515	            return "HH-" + hex;
516	        } catch (NoSuchAlgorithmException e) {
517	            throw new IllegalStateException("SHA-256 algorithm not available", e);
518	        }
519	    }
520	
521	    /**
522	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
523	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
524	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
525	     *
526	     * @param value the raw value, possibly {@code null}
527	     * @return the normalized value
528	     */
529	    private String normalizeForHousehold(String value) {
530	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
531	    }
532	
533	    /**
534	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
535	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
536	     * value yields an empty string.
537	     *
538	     * @param value the raw value, possibly {@code null}
539	     * @return the trimmed, whitespace-collapsed value
540	     */
541	    private String collapseWhitespace(String value) {
542	        if (value == null) {
543	            return "";
544	        }
545	        return value.trim().replaceAll("\\s+", " ");
546	    }
547	
548	    /**
549	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
550	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
551	     * is upper-cased, and common street-type abbreviations are expanded as whole words
552	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
553	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
554	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
555	     *
556	     * @param address the raw address value, possibly {@code null}
557	     * @return the normalized address
558	     */
559	    private String normalizeAddress(String address) {
560	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
561	        if (collapsed.isEmpty()) {
562	            return "";
563	        }
564	        String[] tokens = collapsed.split(" ");
565	        StringBuilder normalized = new StringBuilder();
566	        for (int i = 0; i < tokens.length; i++) {
567	            if (i > 0) {
568	                normalized.append(' ');
569	            }
570	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
571	        }
572	        return normalized.toString();
573	    }
574	
575	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
576	    @Override
577	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
578	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
579	        if (currentOwner == null) {
580	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
581	        }
582	        currentOwner.setAddress(ownerFieldsDto.getAddress());
583	        currentOwner.setCity(ownerFieldsDto.getCity());
584	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
585	        currentOwner.setLastName(ownerFieldsDto.getLastName());
586	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
587	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
588	        this.clinicService.saveOwner(currentOwner);
589	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
590	    }
591	
592	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
593	    @Transactional
594	    @Override
595	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
596	        Owner owner = this.clinicService.findOwnerById(ownerId);
597	        if (owner == null) {
598	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
599	        }
600	        this.clinicService.deleteOwner(owner);
601	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
602	    }
