604	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
605	    @Override
606	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
607	        Owner owner = this.clinicService.findOwnerById(ownerId);
608	        if (owner == null) {
609	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
610	        }
611	        HttpHeaders headers = new HttpHeaders();
612	        Pet pet = petMapper.toPet(petFieldsDto);
613	        owner.setId(ownerId);
614	        pet.setOwner(owner);
615	        pet.getType().setName(null);
616	        this.clinicService.savePet(pet);
617	        PetDto petDto = petMapper.toPetDto(pet);
618	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
619	            .buildAndExpand(pet.getId()).toUri());
620	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
621	    }
